GOLD_REVIEW_UI_HTML = r"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <link rel="icon" href="data:,"><title>Gold Sample v1 人工签核</title>
  <style>
    :root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#182230;background:#f3f5f8}*{box-sizing:border-box}body{margin:0}.top{height:70px;background:#101828;color:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 24px}.top strong{font-size:19px}.progress{font-size:14px;color:#d0d5dd}.layout{display:grid;grid-template-columns:270px minmax(360px,1fr) 510px;height:calc(100vh - 70px)}.pages,.form{background:#fff;overflow:auto;padding:18px}.pages{border-right:1px solid #e1e6ee}.form{border-left:1px solid #e1e6ee}.viewer{padding:22px;overflow:auto}.page{display:flex;align-items:center;justify-content:space-between;padding:11px;border:1px solid #e1e6ee;border-radius:9px;margin:7px 0;cursor:pointer}.page.active{border-color:#2563eb;background:#eff6ff}.page small{display:block;color:#667085;margin-top:3px}.status{font-size:11px;border-radius:999px;padding:4px 7px;background:#fff4d6;color:#8a5b00}.status.done{background:#dcfae6;color:#067647}.source-image{max-width:100%;display:block;margin:auto;background:#fff;box-shadow:0 8px 28px #10182822}.header{display:flex;justify-content:space-between;align-items:start;gap:10px}.tag,.flag{display:inline-block;font-size:11px;border-radius:999px;padding:4px 8px;margin:2px}.tag{background:#eef2f6;color:#344054}.flag{background:#fff4d6;color:#8a5b00}.record{border:1px solid #dce2ea;border-radius:10px;padding:13px;margin:12px 0}.record h3{margin:0 0 9px;font-size:15px}.raw{white-space:pre-wrap;background:#f8fafc;border-radius:7px;padding:10px;font-size:12px;max-height:150px;overflow:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:10px}.full{grid-column:1/-1}label{display:block;color:#475467;font-size:12px;font-weight:700;margin-bottom:4px}input,textarea,select{width:100%;border:1px solid #c9d2df;border-radius:7px;padding:8px;font:inherit}input.missing,textarea.missing{border-color:#f79009;background:#fffaeb}.checks{background:#f8fafc;border:1px solid #e4e7ec;border-radius:10px;padding:12px;margin:15px 0}.checks label{font-size:13px;font-weight:500;margin:8px 0;display:flex;gap:8px;align-items:start}.checks input{width:auto;margin-top:2px}.actions{display:flex;gap:9px;position:sticky;bottom:-18px;background:#fff;padding:14px 0}.actions button{border:0;border-radius:8px;padding:11px 14px;font-weight:700;cursor:pointer}.verify{background:#175cd3;color:#fff}.flag-button{background:#fff1f3;color:#c01048;border:1px solid #fecdd6!important}.notice{padding:10px;border-radius:8px;margin:8px 0;font-size:13px}.error{background:#fff1f3;color:#9f1239}.ok{background:#ecfdf3;color:#067647}.empty{color:#667085;text-align:center;padding:50px 10px}@media(max-width:1100px){.layout{grid-template-columns:240px 1fr;height:auto}.form{grid-column:1/-1;border:0;border-top:1px solid #e1e6ee}}@media(max-width:700px){.top{height:auto;padding:15px;align-items:start}.layout{display:block}.pages{max-height:42vh}.viewer{min-height:420px}.grid{grid-template-columns:1fr}.full{grid-column:auto}}
  </style>
</head>
<body>
  <header class="top"><div><strong>Gold Sample v1 · 人工签核</strong><div style="font-size:12px;color:#98a2b3;margin-top:3px">原页 → 机器预标注 → 明确人工确认</div></div><div class="progress" id="progress">载入中…</div></header>
  <main class="layout">
    <aside class="pages"><div id="pageList"></div></aside>
    <section class="viewer"><div id="viewer" class="empty">选择一页查看冻结原图</div></section>
    <aside class="form"><div id="message"></div><div id="form" class="empty">选择一页开始核验</div></aside>
  </main>
  <script>
    const state={pages:[],current:null};const $=id=>document.getElementById(id);
    const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    async function api(path,options={}){const headers={...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';const response=await fetch(path,{...options,headers});if(!response.ok){let body={};try{body=await response.json()}catch{}throw new Error(body.detail||`请求失败 (${response.status})`)}return response.json()}
    function message(text,type='ok'){$('message').innerHTML=text?`<div class="notice ${type}">${esc(text)}</div>`:''}
    async function loadState(){try{const data=await api('/api/state');state.pages=data.pages;const done=data.readiness.human_verified_count;$('progress').textContent=`${done} / ${data.pages.length} 页 HUMAN_VERIFIED`;$('pageList').innerHTML=data.pages.map(page=>`<div class="page ${state.current?.page_number===page.page_number?'active':''}" data-page="${page.page_number}"><div><strong>第 ${page.page_number} 页</strong><small>${esc(page.layout_tags.join(' · '))} · ${page.entry_count} 词条</small></div><span class="status ${page.review_status==='HUMAN_VERIFIED'?'done':''}">${page.review_status==='HUMAN_VERIFIED'?'已签核':'待核验'}</span></div>`).join('');$('pageList').querySelectorAll('.page').forEach(el=>el.onclick=()=>selectPage(Number(el.dataset.page)))}catch(error){message(error.message,'error')}}
    async function selectPage(page){try{state.current=await api(`/api/pages/${page}`);render();await loadState();if(window.innerWidth<=700)$('viewer').scrollIntoView({behavior:'smooth'})}catch(error){message(error.message,'error')}}
    function render(){const page=state.current;const locked=page.review_status==='HUMAN_VERIFIED';$('viewer').className='';$('viewer').innerHTML=`<div class="header"><h2 style="margin-top:0">冻结原图 · 第 ${page.page_number} 页</h2><span class="status ${locked?'done':''}">${page.review_status}</span></div><img class="source-image" src="${page.image_url}" alt="Gold 原始页 ${page.page_number}">`;
      const tags=page.layout_tags.map(value=>`<span class="tag">${esc(value)}</span>`).join('');const flags=page.review_flags.map(value=>`<span class="flag">${esc(value.replaceAll('_',' '))}</span>`).join('');const records=page.records.map(record=>recordForm(record,locked)).join('');const classification=page.block_count===0?`<div style="margin:14px 0"><label>无机器文本块：请明确页面分类</label><select id="classification" ${locked?'disabled':''}><option value="">请选择</option><option value="IMAGE_ONLY">纯图片页</option><option value="NON_TEXT_PAGE">非文本页</option><option value="FRONT_MATTER">前置页</option></select></div>`:'';
      $('form').className='';$('form').innerHTML=`<div class="header"><div><h2 style="margin:0">${esc(page.sample_id)}</h2><div style="margin-top:6px">${tags}</div></div></div><div style="margin:8px 0">${flags||'<span class="tag">无自动警告</span>'}</div>${records||'<div class="notice ok">机器判断为非词条页；请直接检查原图与文本块完整性。</div>'}${classification}<div class="checks"><strong>四项人工核验</strong><label><input type="checkbox" data-check="source_blocks_match" ${locked?'checked disabled':''}> 原页上的文本或图像区域已被完整覆盖</label><label><input type="checkbox" data-check="entry_boundaries_match" ${locked?'checked disabled':''}> 词条起止与顺序正确，没有合并或遗漏</label><label><input type="checkbox" data-check="canonical_fields_match" ${locked?'checked disabled':''}> lemma、IPA、词性、释义与原页一致</label><label><input type="checkbox" data-check="page_boundaries_match" ${locked?'checked disabled':''}> 跨页与页边界关系正确</label></div><div class="grid"><div><label>真实复核人</label><input id="reviewer" autocomplete="name" value="${esc(page.reviewer_id||sessionStorage.getItem('goldReviewer')||'')}" ${locked?'disabled':''}></div><div class="full"><label>备注 / 问题说明</label><textarea id="notes" rows="3" ${locked?'disabled':''}></textarea></div></div>${locked?'<div class="notice ok">本页已经人工签核。如需修改，应先由维护者显式重新打开。</div>':'<div class="actions"><button class="verify" id="verify">确认本页并签核</button><button class="flag-button" id="flag">发现问题，保持 DRAFT</button></div>'}`;
      if(!locked){$('verify').onclick=verifyPage;$('flag').onclick=flagPage}}
    function recordForm(record,locked){const missing=value=>value==null||value==='';return `<section class="record" data-record="${record.index}"><h3>词条 ${record.index+1} · ${esc(record.lemma)}</h3><div class="raw">${esc(record.raw_text)}</div><div class="grid"><div><label>Lemma</label><input data-field="lemma" value="${esc(record.lemma)}" ${locked?'disabled':''}></div><div><label>Display form</label><input data-field="display_form" value="${esc(record.display_form||'')}" ${locked?'disabled':''}></div><div><label>IPA</label><input data-field="ipa" class="${missing(record.ipa)?'missing':''}" value="${esc(record.ipa||'')}" ${locked?'disabled':''}></div><div><label>词性</label><input data-field="part_of_speech" class="${missing(record.part_of_speech)?'missing':''}" value="${esc(record.part_of_speech||'')}" ${locked?'disabled':''}></div><div class="full"><label>释义</label><textarea data-field="definition" class="${missing(record.definition)?'missing':''}" rows="2" ${locked?'disabled':''}>${esc(record.definition||'')}</textarea></div><div><label>跨页关系</label><select data-field="continuation_type" ${locked?'disabled':''}><option value="" ${!record.continuation_type?'selected':''}>本页完成</option><option value="CROSS_PAGE" ${record.continuation_type==='CROSS_PAGE'?'selected':''}>跨页词条</option></select></div><div><label>来源页（逗号分隔）</label><input data-field="source_pages" value="${esc(record.source_pages.join(','))}" ${locked?'disabled':''}></div></div></section>`}
    function collectRecords(){return [...document.querySelectorAll('[data-record]')].map(section=>{const value=field=>section.querySelector(`[data-field="${field}"]`).value;return {index:Number(section.dataset.record),lemma:value('lemma'),display_form:value('display_form'),ipa:value('ipa'),part_of_speech:value('part_of_speech'),definition:value('definition'),continuation_type:value('continuation_type')||null,source_pages:value('source_pages').split(',').map(item=>Number(item.trim())).filter(Number.isInteger)}})}
    async function verifyPage(){const reviewer=$('reviewer').value.trim();const checks=[...document.querySelectorAll('[data-check]:checked')].map(input=>input.dataset.check);if(!reviewer){message('请填写真实复核人。','error');return}try{await api(`/api/pages/${state.current.page_number}/verify`,{method:'POST',body:JSON.stringify({reviewer_id:reviewer,checks,records:collectRecords(),page_classification:$('classification')?.value||null,notes:$('notes').value})});sessionStorage.setItem('goldReviewer',reviewer);message('本页已记录 HUMAN_VERIFIED。');await loadState();const next=state.pages.find(page=>page.review_status!=='HUMAN_VERIFIED');await selectPage(next?.page_number??state.current.page_number)}catch(error){message(error.message,'error')}}
    async function flagPage(){const reviewer=$('reviewer').value.trim(),notes=$('notes').value.trim();if(!reviewer||!notes){message('标记问题时必须填写复核人和问题说明。','error');return}try{await api(`/api/pages/${state.current.page_number}/flag`,{method:'POST',body:JSON.stringify({reviewer_id:reviewer,notes})});sessionStorage.setItem('goldReviewer',reviewer);message('问题已记录，本页保持 DRAFT。');await selectPage(state.current.page_number)}catch(error){message(error.message,'error')}}
    loadState();
  </script>
</body></html>"""
